from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, OptionalNullable, SdkBaseModel
from .enums.story_citation_resolving_type import StoryCitationResolvingTypeOrStr


class SignalMonitoringPlanNewsletterConfig(SdkBaseModel):
    """Citation settings for newsletters generated by the monitor."""

    citations: OptionalNullable[bool] = UNSET
    """Whether generated newsletters include citations. Defaults to true."""

    story_citation_resolving_type: StoryCitationResolvingTypeOrStr = Field(alias="storyCitationResolvingType")
    """How story citations are resolved. Accepts STORY or TOP_ARTICLE."""


class SignalMonitoringPlanNewsletterConfigDict(TypedDict):
    citations: NotRequired[bool | None]
    story_citation_resolving_type: StoryCitationResolvingTypeOrStr
